{
  "ranking": [
    {
      "id": "patch_89a8d0d71cf0",
      "failure_port": "o_mosi",
      "source_line": 9010,
      "mechanism": "Guards the first command-state entry (state 0) with pre_cmd_state, which is asserted only when the low-level SPI is idle (ll_idle) and ll_cmd_stb is already high. This prevents the command FSM from advancing before the physical SPI engine can accept the first byte, eliminating the early o_mosi toggle observed at cycle 484125."
    },
    {
      "id": "patch_db4e5272cc97",
      "failure_port": "o_mosi",
      "source_line": 8371,
      "mechanism": "Requires pre_cmd_state together with the negation of ll_cmd_stb for the response-state machine reset. This synchronises the rsp_state reset to the exact cycle the low-level transmitter becomes ready, avoiding a premature state machine launch that would drive o_mosi one cycle early."
    },
    {
      "id": "patch_2e6db5d7770e",
      "failure_port": "o_mosi",
      "source_line": 9029,
      "mechanism": "Ands the first state transition with !ll_cmd_stb so the FSM does not leave IDLE until the low-level byte transmitter has actually been strobed. This directly blocks the spurious o_mosi transition that appears when the command state machine runs ahead of the SPI engine."
    },
    {
      "id": "patch_03cf2d2c8b87",
      "failure_port": "o_mosi",
      "source_line": 8636,
      "mechanism": "Makes the pre_cmd_state pulse conditional on !ll_cmd_stb, ensuring the command FSM only samples ll_out_stb/ll_out_dat after the low-level transmitter has returned to idle. Prevents a phantom first byte from being interpreted as a valid R1 response, which would shift the whole MOSI timeline."
    },
    {
      "id": "patch_3a11c0f77d92",
      "failure_port": "o_mosi",
      "source_line": 9820,
      "mechanism": "Qualifies the r_use_fifo branch with r_fifo_wr so the FSM only enters the token-wait state when a FIFO write is actually in progress. Stops an erroneous state hop that would make the transmitter send an extra 0xFF byte, appearing as an early o_mosi edge."
    },
    {
      "id": "patch_46c9544a2141",
      "failure_port": "o_mosi",
      "source_line": 9820,
      "mechanism": "Requires r_have_resp together with r_use_fifo for the GETTOKEN state, ensuring the response token is only expected after the SD card has acknowledged the command. Removes a false token wait that would otherwise keep the SPI engine active one cycle longer."
    },
    {
      "id": "patch_fad6eb05ccdc",
      "failure_port": "o_mosi",
      "source_line": 9820,
      "mechanism": "Blocks the GETTOKEN transition when r_have_resp is still low, preventing the FSM from advancing into a token wait before the physical R1 byte has arrived. Avoids an extra MOSI cycle driven by a premature state change."
    },
    {
      "id": "patch_171aea9942d8",
      "failure_port": "o_mosi",
      "source_line": 9994,
      "mechanism": "Adds r_have_resp to the FIFO-write completion gate so ll_fifo_wr is not dropped until the command response has actually been received. Prevents the SPI engine from idling one cycle early, which would truncate the final MOSI bit."
    }
  ],
  "explanation": "All eight patches gate a state-machine transition with a signal that reflects the true readiness of the low-level SPI transmitter (pre_cmd_state, ll_cmd_stb, ll_idle, r_have_resp, r_fifo_wr). The public trace shows the very first o_mosi edge at cycle 484125 is one cycle early; every selected edit delays a FSM step until the physical SPI engine signals it can accept the next byte, aligning the MOSI timeline with the cycle-exact oracle. Patches that only reorder byte lanes (word_byte_order family) or qualify unrelated FIFO-CRC paths do not touch the command/response handshake and are therefore not ranked."
}
